WITH filtered_products AS (SELECT *, INITCAP(TRIM(category)) AS category_title FROM products WHERE brand = 'Stark' AND cost < 360 AND stock_qty <= 391), products_stats AS (SELECT brand, COUNT(cost) AS cost_count, MAX(stock_qty) AS max_stock_qty FROM filtered_products GROUP BY brand) SELECT brand, cost_count, max_stock_qty FROM products_stats WHERE cost_count > 4 ORDER BY brand, cost_count DESC LIMIT 5;
